  function status(state,message){if(!background&&key===captureKey)setArchiveStatus(state,message);}
  if(cfg.demo){if(!cfg.demoArchive||!cfg.demoNonce){status('demo','Mode coba — hasil tersedia untuk download dan share.');return true;}status('saving','Menyimpan ke Galeri Hasil Test…');try{var testSaved=await postForm(testArchiveForm(blob,key,frameId),90000);status('saved','Tersimpan ke Galeri Hasil Test pribadi.');try{window.dispatchEvent(new CustomEvent('thelove:photo-frame-test-saved',{detail:testSaved||{}}));}catch(e){}return true;}catch(testErr){status('failed','Hasil test belum tersimpan: '+(testErr&&testErr.message?testErr.message:'gagal menyimpan.')+' Download foto ini agar tidak hilang.');return false;}}
  if(!cfg.storageReady){status('unavailable','Galeri pasangan belum terhubung. Download foto ini agar tetap tersimpan di perangkat Anda.');return false;}
